import { existsSync, readdirSync, readFileSync } from "node:fs";
import { basename, resolve } from "../../platform/compat/path/index.js";
import { defineSchema } from "../../schemas/define.js";
import { lazySchema } from "../../schemas/lazy.js";
import { parseRuntimeAgentMarkdownDefinition, } from "./agent-definition.js";
function runtimeAgentDefinitionFileName(v) {
    return v.string().min(1).regex(/^[A-Za-z0-9._-]+\.md$/);
}
function runtimeAgentDefinitionFileId(v) {
    return v.string().min(1).regex(/^[A-Za-z0-9._-]+$/);
}
const runtimeAgentDefinitionFileNameSchema = lazySchema(defineSchema(runtimeAgentDefinitionFileName));
/** Zod schema for resolve runtime agent definitions dir input. */
export const resolveRuntimeAgentDefinitionsDirInputSchema = lazySchema(defineSchema((v) => v.object({
    baseDir: v.string().min(1),
    id: runtimeAgentDefinitionFileId(v),
    fileName: runtimeAgentDefinitionFileName(v).optional(),
})));
export const listRuntimeAgentMarkdownDefinitionIdsInputSchema = lazySchema(defineSchema((v) => v.object({
    baseDir: v.string().min(1),
})));
/** Zod schema for load runtime agent markdown definition from file input. */
export const loadRuntimeAgentMarkdownDefinitionFromFileInputSchema = lazySchema(defineSchema((v) => v.object({
    agentsDir: v.string().min(1),
    id: runtimeAgentDefinitionFileId(v),
    fileName: runtimeAgentDefinitionFileName(v).optional(),
})));
function getRuntimeAgentDefinitionFileName(input) {
    return input.fileName ?? `${input.id}.md`;
}
function hasRuntimeAgentDefinitionFile(path, fileName) {
    return existsSync(resolve(path, fileName));
}
function getRuntimeAgentDefinitionsDirCandidates(baseDir) {
    const firstCandidate = resolve(baseDir, "agents");
    const sourceLayoutCandidate = resolve(baseDir, "../agents");
    const candidates = [
        firstCandidate,
        sourceLayoutCandidate,
        resolve(baseDir, "../../agents"),
        resolve(baseDir, "../../../agents"),
    ];
    return [...new Set(candidates)];
}
/** Resolves runtime agent definitions dir. */
export function resolveRuntimeAgentDefinitionsDir(input) {
    const parsedInput = resolveRuntimeAgentDefinitionsDirInputSchema.parse(input);
    const fileName = getRuntimeAgentDefinitionFileName(parsedInput);
    const candidates = getRuntimeAgentDefinitionsDirCandidates(parsedInput.baseDir);
    const sourceLayoutCandidate = resolve(parsedInput.baseDir, "../agents");
    const fallbackCandidate = basename(parsedInput.baseDir) === "src"
        ? sourceLayoutCandidate
        : resolve(parsedInput.baseDir, "agents");
    return candidates.find((candidate) => hasRuntimeAgentDefinitionFile(candidate, fileName)) ??
        fallbackCandidate;
}
export function listRuntimeAgentMarkdownDefinitionIds(input) {
    const parsedInput = listRuntimeAgentMarkdownDefinitionIdsInputSchema.parse(input);
    const ids = new Set();
    for (const dir of getRuntimeAgentDefinitionsDirCandidates(parsedInput.baseDir)) {
        if (!existsSync(dir)) {
            continue;
        }
        for (const entry of readdirSync(dir, { withFileTypes: true })) {
            if (!entry.isFile()) {
                continue;
            }
            const parseResult = runtimeAgentDefinitionFileNameSchema.safeParse(entry.name);
            if (!parseResult.success) {
                continue;
            }
            ids.add(parseResult.data.slice(0, -".md".length));
        }
    }
    return [...ids].sort((left, right) => left.localeCompare(right));
}
/** Resolves runtime agent markdown definition file path. */
export function resolveRuntimeAgentMarkdownDefinitionFilePath(input) {
    const parsedInput = loadRuntimeAgentMarkdownDefinitionFromFileInputSchema.parse(input);
    return resolve(parsedInput.agentsDir, getRuntimeAgentDefinitionFileName(parsedInput));
}
/** Loads runtime agent markdown definition from file. */
export function loadRuntimeAgentMarkdownDefinitionFromFile(input) {
    const parsedInput = loadRuntimeAgentMarkdownDefinitionFromFileInputSchema.parse(input);
    const filePath = resolveRuntimeAgentMarkdownDefinitionFilePath(parsedInput);
    return parseRuntimeAgentMarkdownDefinition({
        id: parsedInput.id,
        content: readFileSync(filePath, "utf-8"),
    });
}
